% exercise3.m
d = 1;                      % last digit of student number
f2 = 13.2 + 0.17*d;         % = 13.37 Hz
fs = 200;

% --- 1 second recording ---
t1 = 0:1/fs:1-1/fs;
x1 = 0.8*sin(2*pi*15*t1) + 0.4*sin(2*pi*f2*t1);
[f1, P1] = spec(x1, fs, length(x1));

% --- 4 second recording ---
t4 = 0:1/fs:4-1/fs;
x4 = 0.8*sin(2*pi*15*t4) + 0.4*sin(2*pi*f2*t4);
[f4, P4] = spec(x4, fs, length(x4));

% --- 1 second recording, zero-padded to 4x length ---
[fz, Pz] = spec(x1, fs, 4*length(x1));

% --- Print key numbers (window of +/-1 Hz around f2 excludes the 15 Hz peak) ---
fprintf('f2 = %.2f Hz\n', f2); %[output:54c49580]
fprintf('1 s : bin spacing = %.4f Hz, peak near f2 = %.4f\n', fs/length(x1),   max(P1(abs(f1-f2)<1))); %[output:70064a64]
fprintf('4 s : bin spacing = %.4f Hz, peak near f2 = %.4f\n', fs/length(x4),   max(P4(abs(f4-f2)<1))); %[output:6f02933a]
fprintf('pad : bin spacing = %.4f Hz, peak near f2 = %.4f\n', fs/(4*length(x1)), max(Pz(abs(fz-f2)<1))); %[output:402f4916]

% --- Plots ---
figure %[output:1c7988b8]
subplot(3,1,1); plot(f1, P1, '.-'); grid on %[output:1c7988b8]
xlim([0 50]); ylabel('Amplitude'); title('1 second recording') %[output:1c7988b8]

subplot(3,1,2); plot(f4, P4, '.-'); grid on %[output:1c7988b8]
xlim([0 50]); ylabel('Amplitude'); title('4 second recording') %[output:1c7988b8]

subplot(3,1,3); plot(fz, Pz, '.-'); grid on %[output:1c7988b8]
xlim([0 50]); xlabel('Frequency (Hz)'); ylabel('Amplitude') %[output:1c7988b8]
title('1 second, zero-padded (4x)') %[output:1c7988b8]

exportgraphics(gcf, 'leakage-comparison.png', 'Resolution', 300) %[output:1c7988b8]

% ---- local function: must stay at the END of the file ----
function [f, P] = spec(x, fs, Nfft)
N  = length(x);                 % real number of samples
Y  = fft(x, Nfft);              % Nfft > N means zero-padding
P2 = abs(Y/N);                  % divide by N, not Nfft, to keep amplitudes comparable
P  = P2(1:Nfft/2+1);
P(2:end-1) = 2*P(2:end-1);
f  = fs*(0:Nfft/2)/Nfft;
end

